import type { Publication } from './publication-manifest';

export const nov09ResearchPublications: readonly Publication[] = [{"publicationStatus": "reviewed", "kind": "research", "slug": "how-often-do-shared-inboxes-misroute-client-requests", "title": "How often do shared inboxes misroute client requests?", "description": "A method for defining, counting, and reducing misroutes in a shared client inbox without confusing speed with accuracy.", "published": "2026-11-09", "readingMinutes": 8, "heroImage": "/hero/november-9/how-often-do-shared-inboxes-misroute-client-requests-hero.webp", "thumbnail": "/thumbnails/november-9/how-often-do-shared-inboxes-misroute-client-requests.webp", "heroAlt": "How often do shared inboxes misroute client requests?", "topic": "inbox routing", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/research/set-a-shared-inbox-triage-rule-an-assistant-can-defend", "label": "Read the shared inbox triage guide"}, "sources": [{"label": "U.S. Small Business Administration hire and manage employees", "href": "https://www.sba.gov/business-guide/manage-your-business/hire-manage-employees"}, {"label": "NIST SP 800-53 Rev. 5, Security and Privacy Controls", "href": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final"}, {"label": "Plain Language Guidelines, plainlanguage.gov", "href": "https://www.plainlanguage.gov/guidelines/"}], "sections": [{"id": "question-and-scope", "heading": "Question and scope", "paragraphs": ["This review asks how often a shared inbox sends a client request to the wrong owner or queue. The unit is a message that needs action and reaches a person who cannot complete it. The scope covers recurring support and administrative inboxes handled by an assistant or a small team. The review does not estimate a universal misroute rate, because the definition depends on the team's queue design and the client's request mix.", "The question matters because a misroute is invisible in a simple response-time report. The first owner may reply quickly, then forward the message and restart the clock. The client sees a slow answer, while the team sees two fast touches. Measuring the route rather than only the first reply exposes the hidden delay.", "Two definitions keep the count honest. A misroute is a message assigned to an owner who lacks the access or authority to resolve it, while a clarification is a message that needs more information from the client. A message that is correctly routed but waits for a client answer is not a misroute. Separating the two prevents the measure from blaming the assistant for a client delay."]}, {"id": "why-misroutes-happen", "heading": "Why misroutes happen", "paragraphs": ["Most misroutes begin with an intake that does not capture the request type. A message that says please handle this can be read as scheduling, billing, or account support. The assistant chooses the most familiar queue rather than the correct one. A short intake form or a required label removes much of the ambiguity before routing starts.", "A second cause is an outdated owner list. A person leaves, a queue is renamed, or a client contact changes, and the routing rule keeps sending work to the old place. The message is not wrong when it arrives, but no one owns it. Reviewing the owner list on a fixed cadence prevents this quiet failure.", "A third cause is the exception that becomes routine. A request outside the normal service may be forwarded to a senior person who helps once. The next similar request follows the same path even though the queue was never designed for it. Record the exception and decide whether to formalize the route or return the request."]}, {"id": "measure-with-local-data", "heading": "Measure with local data", "paragraphs": ["Start with a two-week log of every message that changed owner after the first assignment. Record the original queue, the final queue, the reason, and the time lost. Ask the assistant to mark the reason at the moment of transfer rather than reconstructing it later. A short list of reasons is easier to apply than a long taxonomy.", "Count the misroutes as a share of actionable messages, not of all messages. Newsletters, automated alerts, and receipts would otherwise dilute the rate. Report the median delay and the slowest cases beside the share. A small number of badly routed messages can matter more than the average suggests.", "Compare the misroute rate with the volume by queue. A queue with few messages may show a high rate because one bad route dominates. A busy queue may hide a similar absolute number of failures. Use both the share and the count when deciding where to change the rule."]}, {"id": "what-evidence-cannot-show", "heading": "What public evidence cannot show", "paragraphs": ["Public management guidance describes the value of clear roles and written procedures, but it does not measure a specific inbox. The Small Business Administration's guidance on managing employees supports clear expectations, not a routing benchmark. NIST security controls address access and accountability rather than message triage. A buyer should use them to justify the design, not to claim a rate.", "A local log also has limits. The assistant may not know that a message was misrouted until the new owner says so. A message that is never answered may not appear in any transfer record. The count is therefore a floor rather than a complete census. State that limit when presenting the result."]}, {"id": "controls-that-reduce-misroutes", "heading": "Controls that reduce misroutes", "paragraphs": ["Publish a small set of request types with one owner and one backup for each. Put the list where the assistant can see it while triaging. Add the fields a complete request needs, such as the client, the system, and the outcome. A request that cannot be classified should go to a named reviewer rather than a random queue.", "Give the assistant a way to reassign a message without losing the clock. The new owner should see the original timestamp and the reason for the transfer. The first owner should not close the message before the new owner accepts it. A clean handoff keeps the delay visible.", "Review the misroutes each week and change one rule at a time. If most failures come from one client or one request type, fix that path first. If the failures are spread across every queue, the intake is probably too vague. Test the change for two weeks and compare the share."]}, {"id": "method-and-limitations", "heading": "Method and limitations", "paragraphs": ["This review describes a measurement method rather than a study of misroute rates across providers. The sources support clear roles and accountable access, but they do not measure a specific inbox. The actual rate depends on the client mix, the tool, the queue design, and the assistant's experience. A team should measure its own inbox before setting a target.", "The log can also change behavior while it is being kept. An assistant who knows the transfer is recorded may ask for help earlier or route more cautiously. That is a useful effect, but it makes the first week a poor baseline. Use a later period for comparison and note when the measurement began."]}, {"id": "decision-checklist", "heading": "Decision checklist", "paragraphs": ["Define a misroute and a clarification separately. Log every owner change with the original queue, the final queue, the reason, and the time lost. Report the share of actionable messages and the slowest cases. Compare the count with the volume by queue.", "Name an owner and a backup for every request type. Give the assistant a short intake and a reviewer for ambiguous messages. Review one rule each week and test the change for two weeks. Record the limit of the local data when presenting the result."]}]}, {"publicationStatus": "reviewed", "kind": "research", "slug": "how-much-rework-comes-from-unclear-meeting-commitments", "title": "How much rework comes from unclear meeting commitments?", "description": "A way to trace rework to missing owners, dates, and decision records, and to test a meeting note standard against real cases.", "published": "2026-11-09", "readingMinutes": 8, "heroImage": "/hero/november-9/how-much-rework-comes-from-unclear-meeting-commitments-hero.webp", "thumbnail": "/thumbnails/november-9/how-much-rework-comes-from-unclear-meeting-commitments.webp", "heroAlt": "How much rework comes from unclear meeting commitments?", "topic": "meeting commitments", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/research/build-a-meeting-prep-packet-an-assistant-can-assemble", "label": "Read the meeting prep packet guide"}, "sources": [{"label": "National Archives, Records Management", "href": "https://www.archives.gov/records-mgmt"}, {"label": "NIST Baldrige Excellence Framework", "href": "https://www.nist.gov/baldrige"}, {"label": "Plain Language Guidelines, plainlanguage.gov", "href": "https://www.plainlanguage.gov/guidelines/"}], "sections": [{"id": "question-and-scope", "heading": "Question and scope", "paragraphs": ["This review asks how much rework can be traced to an unclear commitment made in a meeting. The unit is a task that had to be redone, reassigned, or clarified because the original agreement was ambiguous. The scope covers client and internal meetings where an assistant records decisions and actions. The review does not estimate a universal rework rate, because the work mix and the meeting culture vary by team.", "The question matters because meeting rework is usually charged to the person who executes the task rather than to the meeting that created the ambiguity. A missing owner, an unstated date, or a proposal recorded as a decision can send work in the wrong direction. The cost appears as a second draft, a missed deadline, or a tense clarification call. A team that traces the cause can fix the meeting instead of coaching the executor.", "The review separates rework from a legitimate change of mind. A client who changes a requirement creates new work, while a team that misunderstood the original requirement repeats work. Only the second is a commitment problem. The distinction keeps the measure from blaming the assistant for a decision the client actually changed."]}, {"id": "what-a-commitment-needs", "heading": "What a commitment needs", "paragraphs": ["A usable commitment names the outcome, the owner, the date, and the condition. The outcome should be observable, such as a revised proposal or a confirmed access grant. The owner should be one person who can act. The date should say whether it is a deadline or a target.", "The condition is the part most often missing. A commitment may depend on a client approval, a legal review, or a system change. If the condition is not recorded, the owner looks late when the dependency slips. Write the condition beside the date so the record explains the delay.", "A commitment also needs a status. A proposal, a recommendation, and a final decision are different states. Record which one the meeting reached and who confirmed it. A note that says the team agreed without naming the decision-maker invites a later dispute about authority."]}, {"id": "trace-rework-to-the-record", "heading": "Trace rework to the record", "paragraphs": ["Choose a sample of tasks that were reopened in the past month. For each one, compare the original note with the work that was redone. Mark whether the cause was a missing owner, a missing date, a changed requirement, or a quality problem. Count only the cases where the note would have prevented the rework.", "Ask the person who redid the work what they understood at the start. Their answer often differs from the note in a way that reveals the ambiguity. Record the exact phrase that caused the confusion. The phrase is more useful than a general label because it points to the fix.", "Estimate the time spent on the second pass, including the search for context and the clarification messages. A small number of reworked tasks can consume a large share of a week. Report the hours and the number of cases separately, because one long rework and ten short ones need different fixes. A simple time log kept for two weeks is enough to see the scale."]}, {"id": "why-public-guidance-is-not-a-rate", "heading": "Why public guidance is not a rate", "paragraphs": ["Records management guidance from the National Archives describes records as evidence of business activity. ISO 15489 sets out principles for authentic, reliable, and usable records. Neither source measures how often a meeting note causes rework. They define what a good record should contain, not the performance of a specific team.", "The Baldrige framework supports measurement and improvement in organizational processes. It can justify a local review, but it cannot supply a benchmark for meeting commitments. A buyer should use the framework to ask better questions and then collect local evidence. Quoting a national standard as a rate would overstate what the source says."]}, {"id": "controls-that-reduce-rework", "heading": "Controls that reduce rework", "paragraphs": ["Read each decision and action back before the meeting ends. Ask the owner to confirm the outcome and the date in their own words. Record the confirmation in the note. A thirty-second read-back prevents most of the ambiguity that leads to a second draft.", "Use a template with separate fields for decisions, actions, conditions, and open questions. Do not let a discussion summary stand in for a decision. Require one owner per action and one date per commitment. The structure makes a missing field visible before the note is sent.", "Send the draft note within the day and ask for corrections only on the decisions and actions. A full rewrite invites a new discussion. Store the approved note where the team can find it. Add the note link to the task so the executor does not have to search.", "Review the rework cases each month and change one part of the meeting process. If most failures come from missing dates, add a date check to the read-back. If most come from changed requirements, strengthen the change log rather than the note template. Measure the next month against the same definition."]}, {"id": "method-and-limitations", "heading": "Method and limitations", "paragraphs": ["This review is a practical tracing method rather than a controlled study. The sample depends on which reopened tasks the team can find, and some rework leaves no record at all. The estimate should be treated as a lower bound. A team that wants a firmer number should log rework as it happens.", "The person who reports the cause may also protect a colleague or blame the note. Use the original record and the second draft together rather than a single account. Where the evidence conflicts, mark the case as uncertain. A measure that admits uncertainty is more useful than a confident number built on guesses."]}, {"id": "decision-checklist", "heading": "Decision checklist", "paragraphs": ["Define rework and separate it from a client change of mind. Sample reopened tasks and compare the original note with the second pass. Record the missing field and the exact ambiguous phrase. Estimate the hours and count the cases separately.", "Use a template with decisions, actions, owners, dates, conditions, and open questions. Read the commitments back before the meeting ends. Send the draft note the same day. Review one cause each month and test the change against the same definition."]}]}, {"publicationStatus": "reviewed", "kind": "research", "slug": "what-share-of-vendor-renewals-are-found-after-the-notice-window", "title": "What share of vendor renewals are found after the notice window?", "description": "How to count late-discovered renewals, why notice windows are missed, and which calendar controls prevent a quiet rollover.", "published": "2026-11-09", "readingMinutes": 8, "heroImage": "/hero/november-9/what-share-of-vendor-renewals-are-found-after-the-notice-window-hero.webp", "thumbnail": "/thumbnails/november-9/what-share-of-vendor-renewals-are-found-after-the-notice-window.webp", "heroAlt": "What share of vendor renewals are found after the notice window?", "topic": "renewal notice windows", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/research/keep-a-vendor-renewal-calendar-an-assistant-can-maintain", "label": "Read the vendor renewal calendar guide"}, "sources": [{"label": "U.S. Small Business Administration hire and manage employees", "href": "https://www.sba.gov/business-guide/manage-your-business/hire-manage-employees"}, {"label": "NIST SP 800-53 Rev. 5, Security and Privacy Controls", "href": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final"}, {"label": "NIST Baldrige Excellence Framework", "href": "https://www.nist.gov/baldrige"}], "sections": [{"id": "question-and-scope", "heading": "Question and scope", "paragraphs": ["This review asks what share of vendor renewals are discovered only after the contractual notice window has closed. The unit is a contract that renews automatically and was found too late to cancel or renegotiate before the deadline. The scope covers recurring business services managed by an assistant or a small operations team. The review does not estimate a universal share, because contract terms and recordkeeping practices vary widely.", "The question matters because a late discovery removes the choice the notice window was meant to protect. The team can still ask the vendor for flexibility, but it has lost the leverage of a timely decision. The cost may be a full renewal term, a price increase, or a service the team no longer needs. A decision made after the deadline is usually a negotiation rather than a choice.", "The review separates a renewal that was known but not decided from one that was not known at all. The first is a decision delay, while the second is a recordkeeping failure. Both can produce a rollover, but they need different fixes. A calendar reminder addresses the first, while a contract inventory addresses the second."]}, {"id": "why-notice-windows-are-missed", "heading": "Why notice windows are missed", "paragraphs": ["The most common cause is that the contract dates live in a document rather than in a calendar. The signed file is stored correctly, but no one extracts the end date and the notice period. The renewal arrives as an invoice instead of a decision. A one-time inventory that captures those fields prevents the gap.", "A second cause is a notice method that differs from the assumed one. The contract may require a portal submission or a signed letter, while the team sends an email. The vendor treats the notice as not received, and the renewal proceeds. Record the required method beside the deadline, not only the date.", "A third cause is ownership drift. The person who managed the vendor leaves, and the calendar entry still points to their address. The reminder is sent but no one acts. A named backup and a quarterly owner review keep the reminder connected to a person who can decide."]}, {"id": "measure-the-late-discovery", "heading": "Measure late discovery", "paragraphs": ["Build a list of every contract that renewed in the past year. For each one, record the notice deadline, the date the team became aware of the renewal, and whether a decision was possible. Count the contracts discovered after the deadline. Use the contract date rather than the invoice date as the reference.", "Separate the contracts that were known before the deadline but not decided. Those are a different failure and should not be counted as late discovery. Report both numbers so the team can see whether it needs a better inventory or a faster decision. A single combined rate hides the remedy.", "Check the sample for contracts that renewed without a formal notice because the term rolled over silently. Those are the hardest cases to find and the most useful to include. Ask finance for the recurring charges that have no active contract record. The reconciliation often reveals the missing rows."]}, {"id": "what-public-guidance-can-support", "heading": "What public guidance can support", "paragraphs": ["The Small Business Administration's guidance on managing employees and contractors emphasizes written terms and clear expectations. NIST security controls emphasize accountability and review. Neither source measures renewal notice rates. They support the principle that an obligation should have an owner and a record.", "The Baldrige framework encourages measurement of processes that affect cost and customer value. A renewal calendar fits that principle because it turns a recurring obligation into a reviewable process. The framework does not supply a benchmark. A team should use it to justify the review and then rely on its own contract data."]}, {"id": "controls-that-prevent-rollover", "heading": "Controls that prevent rollover", "paragraphs": ["Create one calendar row per contract with the end date, the notice days, the notice method, the owner, and the contract link. Calculate the notice deadline as its own date. Add a planning reminder at least two weeks before the deadline. The assistant should see the decision date rather than only the renewal date.", "Reconcile the calendar with the bank and card statements each quarter. A recurring charge without a row is an unmanaged obligation. A row without a charge may be a cancelled service that was never removed. Fix both directions before the next budget cycle.", "Give the owner a short decision brief before the deadline: current price, usage, alternatives, and the consequence of renewal. The brief turns a reminder into a decision. Record the outcome and update the contract dates. A renewal that is decided early can still be cancelled if the service is no longer needed.", "Test the notice method with the vendor before the first deadline. Send a low-risk inquiry through the required channel and confirm that it was received. Record the confirmation. A method that fails in a test would have failed at the deadline."]}, {"id": "method-and-limitations", "heading": "Method and limitations", "paragraphs": ["This review describes a measurement and control method rather than a study of renewal rates. The sample depends on the contracts the team can find and the records finance keeps. Some renewals may be missing from both sources. The result should be treated as a minimum count rather than a complete census.", "Contract terms also change through amendments that may not be reflected in the calendar. A renewal date in the original agreement can be superseded by a side letter. The review should include an amendment check before the deadline. Where the terms conflict, the owner should confirm the current version with the vendor."]}, {"id": "decision-checklist", "heading": "Decision checklist", "paragraphs": ["List every contract that renewed in the past year. Record the notice deadline, the discovery date, and whether a decision was possible. Separate late discovery from a delayed decision. Reconcile the list with recurring charges.", "Create one calendar row per contract with the end date, notice days, method, owner, and link. Put the notice deadline on the calendar. Add a planning reminder two weeks earlier. Test the notice method and review the calendar each quarter."]}]}, {"publicationStatus": "reviewed", "kind": "research", "slug": "do-client-onboarding-packs-reduce-first-week-access-delays", "title": "Do client onboarding packs reduce first-week access delays?", "description": "How to measure first-week access delays, what an onboarding pack can control, and where the client dependency remains.", "published": "2026-11-09", "readingMinutes": 8, "heroImage": "/hero/november-9/do-client-onboarding-packs-reduce-first-week-access-delays-hero.webp", "thumbnail": "/thumbnails/november-9/do-client-onboarding-packs-reduce-first-week-access-delays.webp", "heroAlt": "Do client onboarding packs reduce first-week access delays?", "topic": "onboarding access", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/research/design-a-new-client-onboarding-pack-an-assistant-can-own", "label": "Read the client onboarding pack guide"}, "sources": [{"label": "NIST SP 800-63B, Digital Identity Guidelines", "href": "https://pages.nist.gov/800-63-4/sp800-63b.html"}, {"label": "CISA Cyber Essentials", "href": "https://www.cisa.gov/cyber-essentials"}, {"label": "U.S. Small Business Administration hire and manage employees", "href": "https://www.sba.gov/business-guide/manage-your-business/hire-manage-employees"}], "sections": [{"id": "question-and-scope", "heading": "Question and scope", "paragraphs": ["This review asks whether a structured onboarding pack reduces the time an assistant waits for access in the first week. The unit is the interval between the access request and the first working session in the client system. The scope covers recurring assistant roles that need client-owned accounts. The review does not estimate a universal reduction, because the client's provisioning process is often outside the provider's control.", "The question matters because a delayed first week is expensive in a way that is easy to hide. The assistant is paid and available, but the work cannot start. The client may interpret the delay as a slow provider, while the provider is waiting on an approval. Measuring the interval separates the two responsibilities.", "The review separates the provider-controlled steps from the client-controlled steps. Preparing the request, naming the systems, and confirming the contact are provider steps. Creating the account, granting the permission, and enforcing the client's security review are client steps. A pack can improve the first group and make the second group visible, but it cannot remove the client's process."]}, {"id": "what-the-pack-can-control", "heading": "What the pack can control", "paragraphs": ["A pack can list the exact systems, the access level, and the business reason for each request before the start date. A complete request reduces the back-and-forth that often precedes provisioning. It also gives the client a single document to route internally. The assistant does not have to explain the same need in four separate messages.", "A pack can name the client contact who grants each access and the backup who covers absence. It can set the expected request date and the follow-up date. Those fields make the dependency visible without turning the assistant into a project manager. The client can see what is waiting on whom.", "A pack can define the first task that will use the access. A working session with a clear purpose is a better test than a login check. It also gives the client a reason to prioritize the request. Access that is granted but unused is not the same as access that works."]}, {"id": "measure-the-interval", "heading": "Measure the interval", "paragraphs": ["Record the request date, the approval date, the account creation date, and the first successful use. The four dates separate the approval delay from the provisioning delay and the activation delay. A single end-to-end number hides which step to fix. Use the same definition for every new client in the sample.", "Compare the interval before and after the pack with a similar group of clients. If the pack is introduced for everyone at once, compare the first month with the second and note the other changes. A small sample can suggest a direction without proving a universal effect. Report the median and the slowest cases.", "Ask the assistant to record the reason for each wait in a short note. The reason may be a missing approval, a security review, or a client contact who was on leave. Group the reasons at the end of the month. The pattern points to the step that needs a different owner or a better request."]}, {"id": "where-the-client-remains-the-constraint", "heading": "Where the client remains the constraint", "paragraphs": ["The client's security review may take longer than the provider can influence. A new vendor, a sensitive system, or a regulated data set can require a review that the assistant cannot expedite. The pack should state the expected review time and the person who owns it. A provider that promises a date it does not control will damage trust.", "The client may also require a named user, a second factor, or a device check that the assistant must complete. Those steps take time even when the request is perfect. The pack should include them in the first-week plan rather than treating them as surprises. A realistic plan is more useful than an optimistic one."]}, {"id": "controls-that-help", "heading": "Controls that help", "paragraphs": ["Send the access request before the start date and confirm receipt with the named contact. Include the system, the access level, the reason, and the first task. Ask for the expected completion date in writing. A request that is acknowledged is easier to follow up than one that disappears into a queue.", "Set a follow-up cadence that matches the client's process. A daily check may be appropriate for a critical start, while a twice-weekly check may suit a standard role. Put the follow-up on the assistant's queue. Record the response and the next date.", "Prepare a fallback task that does not require the missing access. The assistant can review the brief, draft the first report from available material, or learn the client's terminology. A fallback keeps the first week productive without pretending the access exists. It also reduces the pressure to grant access before the client is ready."]}, {"id": "method-and-limitations", "heading": "Method and limitations", "paragraphs": ["This review describes a measurement method rather than a controlled study of onboarding packs. The sources define identity and access good practice, not the performance of a specific provider. The actual delay depends on the client's systems, the security review, and the people involved. A provider should measure its own cases before claiming an improvement.", "The sample may also be biased toward clients who agreed to the pack. A client with a mature process may adopt it more easily and also provision faster for unrelated reasons. The review should note that possibility. A comparison group or a longer series would strengthen the finding."]}, {"id": "decision-checklist", "heading": "Decision checklist", "paragraphs": ["Define the access interval with request, approval, creation, and first-use dates. List the systems, levels, reasons, and client contacts in one pack. Name the first task that will use the access. Record the reason for each wait.", "Send the request before the start date and confirm receipt. Set a follow-up cadence and put it on the queue. Prepare a fallback task that does not need the access. Report the median and the slowest cases, and state the client dependency."]}]}, {"publicationStatus": "reviewed", "kind": "research", "slug": "how-reliable-are-weekly-status-reports-as-a-record-of-progress", "title": "How reliable are weekly status reports as a record of progress?", "description": "What makes a status report verifiable, where forecasts drift from facts, and how to test a reporting standard against delivery.", "published": "2026-11-09", "readingMinutes": 8, "heroImage": "/hero/november-9/how-reliable-are-weekly-status-reports-as-a-record-of-progress-hero.webp", "thumbnail": "/thumbnails/november-9/how-reliable-are-weekly-status-reports-as-a-record-of-progress.webp", "heroAlt": "How reliable are weekly status reports as a record of progress?", "topic": "status reporting", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/research/write-a-weekly-status-note-that-separates-progress-from-promises", "label": "Read the weekly status note guide"}, "sources": [{"label": "NIST Baldrige Excellence Framework", "href": "https://www.nist.gov/baldrige"}, {"label": "Plain Language Guidelines, plainlanguage.gov", "href": "https://www.plainlanguage.gov/guidelines/"}, {"label": "U.S. Small Business Administration hire and manage employees", "href": "https://www.sba.gov/business-guide/manage-your-business/hire-manage-employees"}], "sections": [{"id": "question-and-scope", "heading": "Question and scope", "paragraphs": ["This review asks how reliable a weekly status report is as a record of what actually happened. The unit is a claim in the report about progress, a blocker, or a forecast. The scope covers recurring client and internal reports written by an assistant or a coordinator. The review does not estimate a universal accuracy rate, because the reporting standard and the work type vary by team.", "The question matters because a status report often becomes the shared memory of a project. A claim that is repeated each week can acquire the authority of a fact even when no one has checked it. A late decision may rest on a progress number that was never verified. Reliability is therefore a governance issue, not only a writing issue.", "The review treats reliability as the match between the report and the underlying evidence. A report can be well written and still unreliable if it omits a missed deadline or presents a hope as a plan. The test is whether a reader can trace each material claim to a source. A report that cannot be traced is a narrative rather than a record."]}, {"id": "what-a-verifiable-claim-looks-like", "heading": "What a verifiable claim looks like", "paragraphs": ["A verifiable progress claim names the output, the date, and the evidence. A sentence such as the vendor list was delivered on Tuesday with a link to the file is testable. A sentence such as the vendor work is progressing is not. The first can be checked by a reader, while the second depends on the writer's judgment.", "A verifiable forecast names the assumption and the next checkpoint. A completion date that depends on a client approval should say so. The reader can then judge whether the assumption is still valid. A forecast without an assumption is a guess with a date attached.", "A verifiable blocker names the dependency, the owner, and the date the decision is needed. It should also say what work can continue while the blocker is open. That last part distinguishes a real constraint from a task the team has chosen to pause. The reader can then act without another meeting."]}, {"id": "where-reports-drift", "heading": "Where reports drift", "paragraphs": ["Reports drift when the writer summarizes activity rather than results. A week of meetings can look productive in a report even when no decision was reached. The reader cannot tell whether the project moved. Requiring at least one completed output per report reduces the drift.", "Reports also drift when bad news travels slowly. A missed date may be described as a revised estimate, and the revision may not be labeled. Each week the gap between the plan and the report grows. A simple rule that every missed date is stated with its cause keeps the record honest.", "A third source of drift is the audience. A report written for an internal manager may omit client-facing risks that the client would consider material. A report written for the client may soften internal problems. The same facts can produce two different records. A shared definition of materiality prevents the gap."]}, {"id": "test-against-delivery", "heading": "Test the report against delivery", "paragraphs": ["Sample four weekly reports and compare each material claim with the work system. Count the claims that are supported, the ones that are partly supported, and the ones that cannot be checked. A claim that cannot be checked is a finding even if it turns out to be true. The test measures the record, not the writer's intent.", "Compare the forecasts in the sample with the dates that were actually met. Record the size and direction of the misses. A forecast that is always early or always late shows a bias that the team can correct. Report the pattern rather than a single miss.", "Ask a reader who did not write the report to identify the most important change of the week. If the reader cannot find it, the report buried the signal. That is a reliability problem for the decision, even when every fact is accurate. Use the answer to revise the order of the sections."]}, {"id": "controls-that-improve-reliability", "heading": "Controls that improve reliability", "paragraphs": ["Use a fixed template with progress, next week, blockers, decisions needed, and metrics. Put the most material change at the top. Require a source link for every completed output. Require a labeled forecast for every future date.", "Review the report before it is sent and check the numbers against the source. Ask the owner of each workstream to confirm the claim that mentions it. A short confirmation prevents a summary from becoming an unsupported fact. Keep the confirmation with the report.", "Publish the definition of material so writers know what must be included. A missed client deadline, a budget change, and a new risk are usually material. A routine task is not. The definition reduces both over-reporting and convenient omission.", "Review the report against delivery once a month. Change one part of the template or the review and compare the next sample. The goal is not a perfect report but a record that a reader can trust for a decision. A small improvement in traceability is worth more than a longer narrative."]}, {"id": "method-and-limitations", "heading": "Method and limitations", "paragraphs": ["This review describes an audit method rather than a study of report accuracy. The sample is small and depends on the records the team keeps. Some claims may be true but undocumented, and the audit will count them as unsupported. That strictness is intentional because the report is meant to be usable by someone who was not there.", "The writer may also change behavior when the reports are audited. A team that knows the sample is coming may add links or delay a claim. That effect can improve the record, but it makes the first sample a poor baseline. Note when the audit began and use a later period for comparison."]}, {"id": "decision-checklist", "heading": "Decision checklist", "paragraphs": ["Define a verifiable progress claim, forecast, and blocker. Sample four reports and compare each material claim with the work system. Count supported, partly supported, and uncheckable claims. Compare forecasts with actual dates.", "Use a fixed template with the most material change first. Require a source for completed work and an assumption for every forecast. Have each workstream owner confirm the claim that mentions it. Review one part of the standard each month."]}]}, {"publicationStatus": "reviewed", "kind": "research", "slug": "what-does-a-purchase-order-log-show-about-approval-bottlenecks", "title": "What does a purchase order log show about approval bottlenecks?", "description": "How to read request, approval, and invoice timestamps to find where a purchase stalls and which control to change first.", "published": "2026-11-09", "readingMinutes": 8, "heroImage": "/hero/november-9/what-does-a-purchase-order-log-show-about-approval-bottlenecks-hero.webp", "thumbnail": "/thumbnails/november-9/what-does-a-purchase-order-log-show-about-approval-bottlenecks.webp", "heroAlt": "What does a purchase order log show about approval bottlenecks?", "topic": "purchase approvals", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/research/run-a-purchase-order-checkpoint-for-an-assistant-managed-inbox", "label": "Read the purchase order checkpoint guide"}, "sources": [{"label": "U.S. Small Business Administration hire and manage employees", "href": "https://www.sba.gov/business-guide/manage-your-business/hire-manage-employees"}, {"label": "NIST SP 800-53 Rev. 5, Security and Privacy Controls", "href": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final"}, {"label": "FTC, Disposing of Your Records", "href": "https://www.ftc.gov/business-guidance/resources/disposing-your-records"}], "sections": [{"id": "question-and-scope", "heading": "Question and scope", "paragraphs": ["This review asks what a purchase order log can show about where an approval process stalls. The unit is a request that needs a purchase order before a vendor can be paid. The scope covers routine operating purchases handled through an assistant-managed inbox. The review does not estimate a universal cycle time, because the approval thresholds and systems vary by organization.", "The question matters because a slow purchase is often described as a vendor problem when the delay sits inside the approval chain. A log with dated steps can show whether the request waited for a budget check, a manager, finance, or the vendor. Without those dates, the team argues from memory. The log turns the argument into a measurable path.", "The review separates the request, approval, order, delivery, and invoice steps. Each step has an owner and a timestamp. A single end-to-end number hides the step that needs a fix. The useful measure is the interval at each step and the share of requests that return for more information."]}, {"id": "what-the-log-should-capture", "heading": "What the log should capture", "paragraphs": ["Capture the request date, the requester, the vendor, the amount, the budget line, and the business reason. Add the approver, the approval date, and the order date. Record the expected delivery and the invoice date. A log with those fields can answer most questions without opening the inbox.", "Record the reason for every return, such as a missing quote, an unfunded budget line, or a wrong approver. A return is a rework event and should be counted. The reason points to the form or the rule that needs to change. Without the reason, the team only knows that the process is slow.", "Keep the log in one system rather than a personal spreadsheet. The assistant and the finance reviewer should see the same record. Add a reference number that appears on the request, the order, and the invoice. A shared reference prevents duplicate entries and lost attachments."]}, {"id": "read-the-intervals", "heading": "Read the intervals", "paragraphs": ["Calculate the median and the slowest cases for each step. The median shows the normal path, while the slowest cases show where the process breaks. A step with a long tail may have a single approver who is often away. A step with a high median may have a rule that is too complex for the risk.", "Compare the intervals by amount and category. A small routine purchase that takes as long as a large contract suggests the threshold is too low. A large purchase that moves quickly may have a dedicated reviewer. Use the comparison to set different paths for different risk levels.", "Count the returns separately from the elapsed time. A request that is returned twice may have a fast approval clock but a slow real cycle. The rework count often explains the tail better than the approval time. Fix the form before adding another approver."]}, {"id": "what-the-log-cannot-show", "heading": "What the log cannot show", "paragraphs": ["The log cannot show a purchase that never entered the process. A person who buys with a personal card and seeks reimbursement later follows a different path. Those purchases are invisible in the purchase order data. A reconciliation with the expense system is needed to find them.", "The log also cannot show the quality of an approval. A fast approval may be a rubber stamp rather than a good decision. A slow approval may include a useful review. Pair the timing with a sample of approved requests to see whether the control is doing its job.", "Public guidance from the Small Business Administration and NIST supports written procedures and accountable access, but it does not supply a benchmark cycle time. The FTC's truth-in-advertising guidance is about accurate promises to customers, not internal approvals. Use the sources to justify the process, then rely on local data for the measurement. They explain why the log matters, not what the result should be."]}, {"id": "controls-that-reduce-the-bottleneck", "heading": "Controls that reduce the bottleneck", "paragraphs": ["Raise the threshold for low-risk, routine purchases and keep the higher review for new vendors and large amounts. A tiered rule lets the assistant move a small request without a manager. The log should show whether the tier reduces the cycle time without increasing exceptions. Review the exceptions after one month before changing the threshold again.", "Give the requester a complete form with the vendor, quote, budget line, and reason. Validate the fields before the request reaches the approver. A returned request is more expensive than a longer form. Test the form on the next ten requests and count the returns.", "Name a backup approver for each threshold and publish the response expectation. A single approver is a single point of failure during leave. The backup should see the same queue and the same rules. Record the delegation in the log.", "Review the log monthly and change one step at a time. If most delays are in approval, adjust the threshold or the backup. If most are in invoice matching, improve the reference field. Compare the next month with the same definitions."]}, {"id": "method-and-limitations", "heading": "Method and limitations", "paragraphs": ["This review describes a log analysis rather than a controlled study of approval times. The data depends on what the team records and when. A timestamp entered later may be approximate. A request that bypasses the log will not appear at all. Treat the result as a guide to where to look rather than a precise audit.", "The log can also change behavior while it is being reviewed. Approvers may clear the queue before the monthly report, which makes the interval look better than usual. Use several months and note the reporting date. A sustained change is more convincing than a single good month."]}, {"id": "decision-checklist", "heading": "Decision checklist", "paragraphs": ["Capture request, approval, order, delivery, and invoice dates with one reference number. Record the reason for every return. Calculate the median and the slowest cases by step. Compare the intervals by amount and category.", "Set tiered thresholds and name a backup for each approver. Validate the request form before approval. Review the log monthly and change one step at a time. Reconcile the log with the expense system to find purchases that bypassed it."]}]}, {"publicationStatus": "reviewed", "kind": "research", "slug": "what-does-a-file-naming-audit-reveal-about-assistant-handoffs", "title": "What does a file naming audit reveal about assistant handoffs?", "description": "How missing fields, duplicate names, and unstable revision markers expose weak handoffs across a distributed assistant team.", "published": "2026-11-09", "readingMinutes": 8, "heroImage": "/hero/november-9/what-does-a-file-naming-audit-reveal-about-assistant-handoffs-hero.webp", "thumbnail": "/thumbnails/november-9/what-does-a-file-naming-audit-reveal-about-assistant-handoffs.webp", "heroAlt": "What does a file naming audit reveal about assistant handoffs?", "topic": "file naming audit", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/research/set-a-client-file-naming-standard-an-assistant-can-apply", "label": "Read the file naming standard guide"}, "sources": [{"label": "National Archives, Records Management", "href": "https://www.archives.gov/records-mgmt"}, {"label": "NIST SP 800-53 Rev. 5, Security and Privacy Controls", "href": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final"}, {"label": "Plain Language Guidelines, plainlanguage.gov", "href": "https://www.plainlanguage.gov/guidelines/"}], "sections": [{"id": "question-and-scope", "heading": "Question and scope", "paragraphs": ["This review asks what an audit of file names can reveal about the quality of a handoff between assistants. The unit is a file that another person must find, open, and use without asking the original owner. The scope covers client documents stored in a shared system by a distributed team. The review does not estimate a universal naming error rate, because each client and system imposes different constraints.", "The question matters because a handoff often fails before anyone opens the file. A name with a missing client, an ambiguous date, or a revision marker that no one understands forces a search. The time lost is small per file and large across a week. The audit makes that cost visible without reading the content.", "The review treats a file name as a retrieval interface rather than a label. A good name tells the next person what the file is, who it belongs to, and which version is current. A bad name may still be accurate to the creator and useless to everyone else. The audit tests the name from the perspective of a reader who was not there."]}, {"id": "what-the-audit-counts", "heading": "What the audit counts", "paragraphs": ["Count the files with a missing client field, an ambiguous date, or no document type. Add the files whose names differ only by a revision marker that is not defined. Those four counts cover most of the retrieval failures in a shared folder. The audit should use the same definition for each folder in the sample.", "Count the duplicate names that point to different content. A duplicate is a sign that two people used the same label for different work. It is also a risk that the wrong file will be sent. Record the folder and the date of the duplicate rather than the full file name, so the sample does not expose client details.", "Measure the time to find a sample of files with and without the standard. Ask a person who did not create the file to locate it using only the folder and the name. Record the search time and whether they opened the wrong file. A direct retrieval test is more meaningful than a count of naming rules."]}, {"id": "what-it-reveals-about-handoffs", "heading": "What it reveals about handoffs", "paragraphs": ["A high count of missing client fields often means the team has more than one naming habit. One assistant uses the client first, while another uses the document type first. The folder looks populated but not searchable. The audit reveals the inconsistency before a client asks for a file.", "A high count of ambiguous dates points to a handoff across regions or systems. One person writes the day first, while another writes the month first. The reader cannot tell which convention applies. A four-digit year and a fixed order remove the ambiguity.", "A high count of undefined revision markers suggests that the approval step is unclear. People use final, v2, and latest without agreeing on what each means. The next person may send the wrong version to a client. The audit connects a naming problem to a control problem."]}, {"id": "limits-of-the-audit", "heading": "Limits of the audit", "paragraphs": ["The audit sees the names, not the content or the access controls. A well-named file can still be in the wrong folder or visible to the wrong people. A poorly named file can be perfectly secure. Use the audit with an access review rather than as a substitute.", "The sample may overrepresent the folders that are easy to list. A shared drive with nested permissions may hide the folders where the worst names live. Ask the team which folder causes the most searching. Include that folder even if it is inconvenient to sample.", "Records management guidance from the National Archives and ISO 15489 supports the idea that records should be findable and usable. NIST access controls support the protection of the files. Neither source defines a naming convention for a specific client. The audit should use local rules and the client's contract, not a generic template."]}, {"id": "controls-that-improve-handoffs", "heading": "Controls that improve handoffs", "paragraphs": ["Publish a short standard with the fields, the order, and one example. Keep it to one page so the team can apply it during a busy day. Put the standard where files are created, not only in a policy folder. A rule that requires a search to find will not be used.", "Add the name check to the handoff step. The person who sends a file should confirm the client, the type, the date, and the revision before attaching it. A second reader should be able to find the file from the name alone. The check takes seconds and prevents the most common wrong-file error.", "Migrate one active folder at a time and keep a mapping table. Test the links after the rename. Leave the archive alone unless a client requests a change. A migration that breaks old references creates more work than the standard saves.", "Review a sample each month and change one field at a time. If the client field is missing, fix the template or the training. If the revision marker is unclear, define the approval states. Compare the next sample with the same counts."]}, {"id": "method-and-limitations", "heading": "Method and limitations", "paragraphs": ["This review describes an audit method rather than a study of naming errors across providers. The sample depends on the folders the team can access and the time available to test retrieval. Some files may be named correctly for a system that the auditor does not know. The result should be discussed with the team before it is treated as a failure.", "The audit can also encourage cosmetic renaming without fixing the handoff. A team may add a client code to every file while leaving the revision process unclear. Pair the naming check with a review of the actual handoff and the approval record. The name is a symptom, not the whole control."]}, {"id": "decision-checklist", "heading": "Decision checklist", "paragraphs": ["Count missing client fields, ambiguous dates, undefined revisions, and duplicate names. Test retrieval with a person who did not create the file. Include the folder the team says causes the most searching. Record the limits of the sample.", "Publish a one-page standard with fields, order, and an example. Add the name check to the handoff step. Migrate one active folder at a time with a mapping table. Review one field each month and compare the counts."]}]}];
